SET NAMES utf8mb4;
USE forgex_common;

ON DUPLICATE KEY UPDATE
  text_i18n_json = VALUES(text_i18n_json),
  enabled = VALUES(enabled),
  update_by = VALUES(update_by),
  update_time = CURRENT_TIMESTAMP;

SELECT module, COUNT(*) AS integration_i18n_count
FROM fx_i18n_message
WHERE module = 'integration'
  AND deleted = 0
GROUP BY module;
